package com.perkvault.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import android.graphics.PixelFormat;import android.provider.Settings;
public class Bubble extends Service {WindowManager wm;Button bubble;boolean open=false;public IBinder onBind(Intent i){return null;}public int onStartCommand(Intent i,int flags,int id){if(!Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}NotificationManager nm=getSystemService(NotificationManager.class);nm.createNotificationChannel(new NotificationChannel("bubble","Floating shortcut",NotificationManager.IMPORTANCE_LOW));PendingIntent pi=PendingIntent.getActivity(this,1,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE);startForeground(1,new Notification.Builder(this,"bubble").setSmallIcon(android.R.drawable.ic_menu_save).setContentTitle("PerkVault shortcut enabled").setContentText("Open PerkVault to stop before payment").setContentIntent(pi).build());if(bubble!=null)return START_NOT_STICKY;wm=getSystemService(WindowManager.class);bubble=new Button(this);bubble.setText("+V");WindowManager.LayoutParams p=new WindowManager.LayoutParams(140,140,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);p.gravity=Gravity.TOP|Gravity.LEFT;p.x=10;p.y=300;bubble.setOnTouchListener(new View.OnTouchListener(){float x,y;int px,py;public boolean onTouch(View v,android.view.MotionEvent e){switch(e.getAction()){case 0:x=e.getRawX();y=e.getRawY();px=p.x;py=p.y;return true;case 2:p.x=px+(int)(e.getRawX()-x);p.y=py+(int)(e.getRawY()-y);wm.updateViewLayout(bubble,p);return true;case 1:if(Math.abs(e.getRawX()-x)+Math.abs(e.getRawY()-y)<20&&!open){open=true;Capture.show(Bubble.this,"",()->open=false);}return true;}return false;}});wm.addView(bubble,p);return START_NOT_STICKY;}public void onDestroy(){if(bubble!=null)wm.removeView(bubble);super.onDestroy();}}
